import{_ as r,a0 as l,w as o,s,ao as g,I as a,x as n,a1 as p,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"五个 ping 工具的使用实例 | LCTT x X-CMD","titleTemplate":false,"description":"五个 ping 工具的使用实例 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"五个 ping 工具的使用实例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"五个 ping 工具的使用实例 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Five Examples Of The ping Utility","title":"五个 ping 工具的使用实例","tag":"201311","desc":""},"relativePath":"201311/Five Examples Of The ping Utility.md","filePath":"[post].md"}'),d={name:"201311/Five Examples Of The ping Utility.md"};function h(m,e,c,u,f,x){const i=l("Link");return o(),s("div",null,[e[11]||(e[11]=g(`<h1 id="五个-ping-工具的使用实例" tabindex="-1">五个 ping 工具的使用实例 <a class="header-anchor" href="#五个-ping-工具的使用实例" aria-label="Permalink to “五个 ping 工具的使用实例”">​</a></h1><h3 id="什么是-ping-工具" tabindex="-1">什么是 ping 工具### <a class="header-anchor" href="#什么是-ping-工具" aria-label="Permalink to “什么是 ping 工具###”">​</a></h3><p>在讲述一些关于ping工具真实直观的使用实例前，先让我来介绍一下这个命令行工具及其目的。ping工具通常用来测试一台主机在互联网协议(IP)网络内的可达性。其名字源于主动声纳法——在水下创建一个脉冲声音信号(ping)并侦听周围物体的返回信号。该方法同样生动描述了ping网络工具的工作原理。ping工具对一台主机发送回应请求然后等待ICMP响应。</p><p>实践中的ping工具的一些例子：</p><h3 id="查询主机的ip地址" tabindex="-1">查询主机的IP地址 <a class="header-anchor" href="#查询主机的ip地址" aria-label="Permalink to “查询主机的IP地址”">​</a></h3><p>有时候你需要得到某一台主机的IP地址，如图一。只需要键入ping命令后面跟上要查询的主机名。</p><pre><code>ping www.omgubuntu.com
</code></pre><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/ping1.png" alt=""></p><h3 id="查询正在使用的ping工具的版本信息" tabindex="-1">查询正在使用的ping工具的版本信息 <a class="header-anchor" href="#查询正在使用的ping工具的版本信息" aria-label="Permalink to “查询正在使用的ping工具的版本信息”">​</a></h3><p>用 -V 选项可以用来查询你手头上ping工具的版本信息。键入下列命令显示正在使用的ping工具的版本信息。</p><pre><code>ping -V
</code></pre><p>正如你从图二见到的，我正在使用的是“ping utility,iputils-sss20101006”</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/ping2.png" alt=""></p><h3 id="自动退出-ping" tabindex="-1">自动退出 ping <a class="header-anchor" href="#自动退出-ping" aria-label="Permalink to “自动退出 ping”">​</a></h3><p>当你用‘ping 主机’命令ping一台机器时，ping自己无法停止，你必需按下CTRL+C强行退出，或者你可以用 -c (count)选项指定发送包的数量。使用-c选项，当网络管理员(其实普通用户也可以)发送完指定数量的包之后，无需按CTRL+C，ping进程就会自动停止。</p><pre><code>ping -c 13 127.0.0.1
</code></pre><p>上列的命令发送了13个包到我的本地主机上。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/ping3.png" alt=""></p><p>正如你从图三看到的，我并没有按CTRL+C，而ping自动退出了。</p><h3 id="指定数据包之间的时间间隔" tabindex="-1">指定数据包之间的时间间隔 <a class="header-anchor" href="#指定数据包之间的时间间隔" aria-label="Permalink to “指定数据包之间的时间间隔”">​</a></h3><p>你知道ping每秒钟发送一个数据包吗？你喜欢快一点还是慢一点？用 -i 选项能指定包之间的时间间隔。用下列命令快速发送或慢速发送包。</p><h3 id="每0-13秒发送一个包" tabindex="-1">每0.13秒发送一个包 <a class="header-anchor" href="#每0-13秒发送一个包" aria-label="Permalink to “每0.13秒发送一个包”">​</a></h3><pre><code>ping -i 0.13
</code></pre><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/ping4.png" alt=""></p><h3 id="每13秒发送一个包" tabindex="-1">每13秒发送一个包 <a class="header-anchor" href="#每13秒发送一个包" aria-label="Permalink to “每13秒发送一个包”">​</a></h3><pre><code>ping -i 13
</code></pre><h3 id="结合-i-选项和-c-选项" tabindex="-1">结合 -i 选项和 -c 选项 <a class="header-anchor" href="#结合-i-选项和-c-选项" aria-label="Permalink to “结合 -i 选项和 -c 选项”">​</a></h3><pre><code>ping -c 13 -i 3
</code></pre><p>总共花费39秒发出13个数据包，数据包的时间间隔为三秒。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/ping6.png" alt=""></p><hr>`,31)),a("p",null,[e[1]||(e[1]=n("via: ",-1)),p(i,{href:"http://www.unixmen.com/five-examples-ping-utility/"},{default:t(()=>[...e[0]||(e[0]=[n("http://www.unixmen.com/five-examples-ping-utility/",-1)])]),_:1})]),a("p",null,[e[4]||(e[4]=n("译者：",-1)),p(i,{href:"https://github.com/Luoxcat"},{default:t(()=>[...e[2]||(e[2]=[n("Luoxcat",-1)])]),_:1}),e[5]||(e[5]=n(" 校对：",-1)),p(i,{href:"http://blog.csdn.net/tinyeyeser"},{default:t(()=>[...e[3]||(e[3]=[n("Mr小眼儿",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=n("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[6]||(e[6]=[n("LCTT",-1)])]),_:1}),e[9]||(e[9]=n(" 原创翻译，",-1)),p(i,{href:"http://linux.cn/"},{default:t(()=>[...e[7]||(e[7]=[n("Linux中国",-1)])]),_:1}),e[10]||(e[10]=n(" 荣誉推出",-1))])])}const P=r(d,[["render",h]]);export{b as __pageData,P as default};
